// A bounded transactional index: validation must precede mutation.
use std::collections::BTreeMap;

#[derive(Debug, PartialEq)]
enum Failure { Duplicate(u64), Missing(u64), Capacity, Overflow }

struct Index { entries: BTreeMap<u64, i64>, revision: u64, limit: usize }

impl Index {
    fn insert_batch(&mut self, incoming: &[(u64, i64)]) -> Result<u64, Failure> {
        let next = self.revision.checked_add(1).ok_or(Failure::Overflow)?;
        let total = self.entries.len().checked_add(incoming.len()).ok_or(Failure::Capacity)?;
        if total > self.limit { return Err(Failure::Capacity); }
        let mut staged = BTreeMap::new();
        for &(key, value) in incoming {
            if self.entries.contains_key(&key) || staged.insert(key, value).is_some() {
                return Err(Failure::Duplicate(key));
            }
        }
        self.entries.extend(staged);
        self.revision = next;
        Ok(next)
    }

    fn remove(&mut self, key: u64) -> Result<i64, Failure> {
        let next = self.revision.checked_add(1).ok_or(Failure::Overflow)?;
        let value = self.entries.remove(&key).ok_or(Failure::Missing(key))?;
        self.revision = next;
        Ok(value)
    }
}

// Consider the empty batch, a duplicate inside incoming, and a saturated revision.
// The caller must distinguish rejected transactions from successfully empty ones.
fn scenario() {
    let mut index = Index { entries: BTreeMap::new(), revision: 7, limit: 3 };
    assert_eq!(index.insert_batch(&[(11, -4), (29, 18)]), Ok(8));
    assert_eq!(index.insert_batch(&[(31, 6), (37, 9)]), Err(Failure::Capacity));
    assert_eq!(index.remove(11), Ok(-4));
    assert_eq!(index.entries.get(&29), Some(&18));
}
